header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan($root){global $TEXT;$files=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){$p=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isFile())$files[$p]=$f->getSize();}ksort($files);$refs=[];$rx=["/\b(?:require|require_once|include|include_once)\s*\(?\s*['\"]([^'\"]+)['\"]/i","/\b(?:import|export)\s+(?:[^'\";]+?\s+from\s+)?['\"]([^'\"]+)['\"]/i","/\b(?:src|href)\s*=\s*['\"]([^'\"]+)['\"]/i"];foreach($files as $p=>$size){if($size>700000||!preg_match($TEXT,$p))continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;foreach($rx as $re){preg_match_all($re,$s,$m);foreach(array_unique($m[1]??[]) as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if(!$v||preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))continue;$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}}return['files'=>array_keys($files),'sizes'=>$files,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan($ROOT);
function safePath($p){global $D,$TEXT; $p=ltrim(str_replace('\\','/',(string)$p),'/');return $p&&$p!=='site-wire-live.php'&&!blocked($p)&&isset($D['sizes'][$p])&&preg_match($TEXT,$p);}
if(isset($_GET['pulse'])){header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s'),'files'=>count($D['files']),'relations'=>count($D['refs'])]);exit;}
if(isset($_GET['read'])){$p=ltrim(str_replace('\\','/',$_GET['read']),'/');if(!safePath($p)){http_response_code(403);echo json_encode(['error'=>'File not editable']);exit;}header('Content-Type:application/json');echo json_encode(['path'=>$p,'content'=>@file_get_contents($ROOT.'/'.$p)?:'']);exit;}
if(isset($_POST['save'],$_POST['path'],$_POST['content'])){$p=ltrim(str_replace('\\','/',$_POST['path']),'/');if(!safePath($p)){http_response_code(403);echo json_encode(['ok'=>0,'error'=>'File cannot be edited']);exit;}$ok=@file_put_contents($ROOT.'/'.$p,$_POST['content'],LOCK_EX);header('Content-Type:application/json');echo json_encode(['ok'=>$ok!==false,'message'=>$ok!==false?'Saved':'Save failed']);exit;}
if(isset($_POST['create'],$_POST['path'],$_POST['content'])){$p=ltrim(str_replace('\\','/',$_POST['path']),'/');if(!$p||blocked($p)||$p==='site-wire-live.php'||file_exists($ROOT.'/'.$p)||!preg_match($TEXT,$p)){http_response_code(400);echo json_encode(['ok'=>0,'error'=>'Invalid or existing file']);exit;}if(!is_dir(dirname($ROOT.'/'.$p)))@mkdir(dirname($ROOT.'/'.$p),0755,true);$ok=@file_put_contents($ROOT.'/'.$p,$_POST['content'],LOCK_EX);header('Content-Type:application/json');echo json_encode(['ok'=>$ok!==false,'message'=>$ok!==false?'Created':'Create failed']);exit;}
