*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#071016;color:#dce8ed;font-family:system-ui,sans-serif}.head{height:56px;border-bottom:1px solid #203139;padding:10px 15px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:750;font-size:15px}.brand b{color:#55dfce}.stats{font:8px monospace;color:#70858d}.app{height:calc(100% - 56px);display:flex}.folders{width:230px;border-right:1px solid #203139;padding:11px;overflow:auto}.folders h4{margin:0 0 8px;color:#607780;font:8px monospace}.search{width:100%;padding:8px;background:#09151b;border:1px solid #263d45;border-radius:6px;color:#fff;outline:0;font:9px monospace;margin-bottom:6px}.folder{padding:7px;border-radius:5px;color:#9aadb4;font:9px monospace;cursor:pointer;display:flex;justify-content:space-between}.folder:hover,.folder.active{background:#102128;color:#64ded2}.count{color:#526b74}.main{flex:1;min-width:0;display:flex;flex-direction:column}.bar{height:40px;border-bottom:1px solid #203139;padding:7px 10px;display:flex;align-items:center;gap:5px}.crumb{font:8px monospace;color:#70858d;margin-right:auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.button,.filter{border:1px solid #263d45;background:#09151b;color:#849aa2;border-radius:5px;padding:6px 9px;font:8px monospace;cursor:pointer}.button:hover,.filter:hover,.filter.active{color:#64ded2;border-color:#55dfce66}.tabs{height:34px;border-bottom:1px solid #203139;display:flex;overflow:auto}.tab{min-width:130px;max-width:190px;padding:9px 11px;border-right:1px solid #203139;color:#718890;font:8px monospace;cursor:pointer;white-space:nowrap}.tab.active{background:#0b171d;color:#dcecef;border-top:1px solid #55dfce}.tab .x{float:right;margin-left:10px;color:#50656d}.files{height:120px;border-bottom:1px solid #203139;padding:8px;overflow:auto;display:flex;flex-wrap:wrap;align-content:flex-start;gap:5px}.file{border:1px solid #263d45;background:#0a151b;border-radius:5px;padding:7px 9px;color:#91a5ac;font:8px monospace;cursor:pointer;white-space:nowrap}.file:hover,.file.active{border-color:#55dfce;color:#e9ffff}.editor{flex:1;min-height:0;display:flex;flex-direction:column}.editorhead{height:31px;border-bottom:1px solid #203139;padding:7px 10px;font:8px monospace;color:#647d86;display:flex;justify-content:space-between}.dirty{color:#f2c36b}.codewrap{flex:1;display:flex;min-height:0;overflow:auto;background:#060c11}.lines{width:48px;flex:none;padding:15px 8px;text-align:right;color:#40545d;font:12px/1.6 'Cascadia Code','Consolas',monospace;user-select:none}.code{flex:1;resize:none;border:0;outline:0;background:#060c11;color:#d7e4e8;padding:15px 15px 30px 8px;font:12px/1.6 'Cascadia Code','Consolas',monospace;tab-size:2;white-space:pre;overflow:auto}.right{width:275px;border-left:1px solid #203139;padding:13px;overflow:auto}.right h3{margin:5px 0;font-size:13px}.tag{color:#59757f;font:7px monospace;letter-spacing:1px}.path{color:#55dfce;font:8px monospace;word-break:break-all}.summary{display:flex;gap:4px;margin-top:10px}.stat{flex:1;background:#0d1c22;border-radius:5px;padding:7px}.stat b{display:block;font:12px monospace}.stat span{font:7px monospace;color:#58717a}.list{margin-top:9px;font:8px monospace;color:#8da1a8;line-height:1.8}.status{position:fixed;right:15px;bottom:9px;color:#607982;font:8px monospace}.led{display:inline-block;width:6px;height:6px;border-radius:50%;background:#5be5bb;margin-right:6px}.notice{position:fixed;right:15px;bottom:28px;background:#102128;border:1px solid #29434b;padding:7px 10px;border-radius:5px;font:8px monospace;display:none}.notice.show{display:block}@media(max-width:850px){.right{display:none}.folders{width:185px}.stats{display:none}}@media(max-width:600px){.folders{width:150px}.files{height:95px}.filter{display:none}}
</style></head><body><header class="head"><div class="brand"><b>◇</b> SmartToolz Relationship Manager <span style="color:#607780;font-size:9px">/ IDE</span></div><div class="stats"><?php echo count($D['files']);?> files · <?php echo count($D['refs']);?> relations · <span style="color:#55dfce">LIVE</span></div></header><div class="app"><aside class="folders"><h4>EXPLORER</h4><input id="search" class="search" placeholder="Search files…"><div id="folderList"></div></aside><main class="main"><div class="bar"><span id="crumb" class="crumb">Select a folder</span><button class="filter active" data-type="all">ALL</button><button class="filter" data-type="php">PHP</button><button class="filter" data-type="js">JS</button><button class="filter" data-type="css">CSS</button><button id="newFile" class="button">NEW</button><button id="save" class="button">SAVE</button><button id="refresh" class="button">RESCAN</button></div><div id="tabs" class="tabs"></div><div id="files" class="files"><span style="font:8px monospace;color:#526a73">Select a folder.</span></div><section class="editor"><div class="editorhead"><span id="editorHead">NO FILE OPEN</span><span id="dirty"></span></div><div class="codewrap"><div id="lines" class="lines">1</div><textarea id="code" class="code" spellcheck="false" placeholder="Select a text file to edit…"></textarea></div></section></main><aside class="right"><div class="tag">RELATIONSHIPS</div><h3 id="rn">No file selected</h3><div id="rp" class="path"></div><div class="summary"><div class="stat"><b id="inc">0</b><span>IN</span></div><div class="stat"><b id="out">0</b><span>OUT</span></div><div class="stat"><b id="total">0</b><span>TOTAL</span></div></div><div id="rl" class="list"></div></aside></div><div id="notice" class="notice"></div><div class="status"><span class="led"></span><b id="status">LIVE</b></div><script>
var DATA=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?>,current='',selected='',filter='all',tabs=[],original='';function el(id){return document.getElementById(id)}function folders(){var a={};DATA.files.forEach(function(f){a[f.split('/')[0]]=1});return Object.keys(a).sort()}function direct(folder){return DATA.files.filter(function(f){var r=f.substring(folder.length+1);return f.indexOf(folder+'/')===0&&r.indexOf('/')===-1})}function ok(f){if(filter==='all')return true;var e=(f.split('.').pop()||'').toLowerCase();if(filter==='php')return e==='php';if(filter==='js')return ['js','mjs','jsx','ts','tsx'].indexOf(e)>=0;if(filter==='css')return ['css','scss'].indexOf(e)>=0;return true}
function renderFolders(q){var b=el('folderList');b.innerHTML='';q=(q||'').toLowerCase();folders().forEach(function(f){if(q&&f.toLowerCase().indexOf(q)<0&&!DATA.files.some(function(x){return x.indexOf(f+'/')===0&&x.toLowerCase().indexOf(q)>=0}))return;var d=document.createElement('div');d.className='folder '+(f===current?'active':'');d.innerHTML='<span>▸ '+f+'</span><span class="count">'+direct(f).length+'</span>';d.onclick=function(){openFolder(f)};b.appendChild(d)})}
function openFolder(f){current=f;el('crumb').textContent=f+' /';var b=el('files');b.innerHTML='';var a=direct(f).filter(ok);if(!a.length)b.innerHTML='<span style="font:8px monospace;color:#526a73">No matching files.</span>';a.forEach(function(p){var d=document.createElement('button');d.className='file';d.textContent='▸ '+p.split('/').pop();d.onclick=function(){openFile(p)};b.appendChild(d)});renderFolders(el('search').value)}
function renderTabs(){var b=el('tabs');b.innerHTML='';tabs.forEach(function(p){var d=document.createElement('div');d.className='tab '+(p===selected?'active':'');d.textContent=p.split('/').pop();var x=document.createElement('span');x.className='x';x.textContent='×';x.onclick=function(e){e.stopPropagation();closeTab(p)};d.appendChild(x);d.onclick=function(){openFile(p)};b.appendChild(d)})}
function openFile(p){if(tabs.indexOf(p)<0)tabs.push(p);selected=p;renderTabs();el('editorHead').textContent=p;fetch(location.pathname+'?read='+encodeURIComponent(p)).then(function(r){return r.json()}).then(function(d){if(d.error)throw Error(d.error);original=d.content;el('code').value=d.content;dirty();lines();relation(p)}).catch(function(e){notice(e.message)})}
function closeTab(p){var i=tabs.indexOf(p);tabs.splice(i,1);if(selected===p){selected=tabs[Math.max(0,i-1)]||'';if(selected)openFile(selected);else{el('code').value='';el('editorHead').textContent='NO FILE OPEN';el('lines').textContent='1';relation('')}}renderTabs()}
function dirty(){el('dirty').textContent=selected&&el('code').value!==original?'● UNSAVED':'';el('dirty').className=selected&&el('code').value!==original?'dirty':''}function lines(){var n=Math.max(1,el('code').value.split('\n').length);el('lines').textContent=Array.from({length:n},function(_,i){return i+1}).join('\n')}
function relation(p){if(!p){el('rn').textContent='No file selected';el('rp').textContent='';el('inc').textContent=el('out').textContent=el('total').textContent='0';el('rl').textContent='';return}var inc=DATA.refs.filter(function(r){return r.to===p}),out=DATA.refs.filter(function(r){return r.from===p});el('rn').textContent=p.split('/').pop();el('rp').textContent=p;el('inc').textContent=inc.length;el('out').textContent=out.length;el('total').textContent=inc.length+out.length;var a=[];inc.forEach(function(r){a.push('← '+r.from)});out.forEach(function(r){a.push('→ '+r.to)});el('rl').innerHTML=a.length?a.join('<br>'):'No direct relationships'}function notice(s){var n=el('notice');n.textContent=s;n.classList.add('show');setTimeout(function(){n.classList.remove('show')},2200)}
el('save').onclick=function(){if(!selected){notice('Open a file first');return}fetch(location.pathname,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'save=1&path='+encodeURIComponent(selected)+'&content='+encodeURIComponent(el('code').value)}).then(function(r){return r.json()}).then(function(d){if(!d.ok)throw Error(d.error||'Save failed');original=el('code').value;dirty();notice('Saved')}).catch(function(e){notice(e.message)})};el('newFile').onclick=function(){var p=prompt('New file path, e.g. pages/test.php');if(!p)return;fetch(location.pathname,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'create=1&path='+encodeURIComponent(p)+'&content='+encodeURIComponent('')}).then(function(r){return r.json()}).then(function(d){if(!d.ok)throw Error(d.error||'Create failed');notice('Created '+p);location.reload()}).catch(function(e){notice(e.message)})};el('refresh').onclick=function(){if(selected&&el('code').value!==original&&!confirm('Discard unsaved changes?'))return;location.reload()};el('search').oninput=function(){renderFolders(this.value);if(current)openFolder(current)};document.querySelectorAll('.filter').forEach(function(b){b.onclick=function(){document.querySelectorAll('.filter').forEach(function(x){x.classList.remove('active')});b.classList.add('active');filter=b.dataset.type;if(current)openFolder(current)}});el('code').addEventListener('input',function(){dirty();lines()});el('code').addEventListener('keydown',function(e){if(e.key==='Tab'){e.preventDefault();var a=this.selectionStart,b=this.selectionEnd;this.value=this.value.substring(0,a)+'  '+this.value.substring(b);this.selectionStart=this.selectionEnd=a+2;dirty();lines()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();el('save').click()}});renderFolders('');setInterval(function(){fetch(location.pathname+'?pulse=1&_='+Date.now(),{cache:'no-store'}).then(function(r){return r.json()}).then(function(d){el('status').textContent='LIVE · '+d.time}).catch(function(){el('status').textContent='OFFLINE'})},3000);
</script></body></html>